    r.graphic = s.defaultGraphic; r.scale = scale;
    if (def) r.graphic = def; else r.scale = scale * 0.33333334f;
    r.layer = s.types[slot] == 1 ? 0x45 : 0x44;
    r.drawn = true;
    return r;
}

