#include <cstdio>
#include <cmath>

struct M { float e[4][3]; };
static void Mul(M& r, const M& a, const M& b)
{
    for (int i = 0; i < 4; ++i)
        for (int j = 0; j < 3; ++j)
            r.e[i][j] = a.e[i][0] * b.e[0][j] + a.e[i][1] * b.e[1][j] + a.e[i][2] * b.e[2][j] + (i == 3 ? b.e[3][j] : 0.0f);
